-- data/items.lua: one Item record per inventory code 0x01..0x32 (spells 0x33..0x40 live in data/spells.lua).
-- Sources [C]: record 0xD4540 + 0x30*(code-1) (doc 08): +0x00 name, +0x1A icon tilemap, +0x1E detail tilemap,
--   +0x22 price base (shops 0x57A48/0x585AC, adjusted by 0x57A6E), +0x24..+0x27 kind-specific bytes.
--   kind: repo items.lua (all 50 prices/magazines/armor values match the ROM, doc 08 diff).
-- Weapons (0x01..0x0F) also have a full Weapon record in data/weapons.lua; Item:weapon() links to it.
-- Generated by tools/gen_records.py items; regenerate rather than hand-edit.
local E = require("enums")
local ItemKind = E.ItemKind

---@class Item
---@field id integer  @field name string  @field kind integer ItemKind  @field price integer +0x22
---@field b24 integer @field b25 integer  @field b26 integer  @field b27 integer  raw bytes, read via the accessors below
local Item = {}
Item.__index = Item
setmetatable(Item, { __call = function(_, t) return setmetatable(t, Item) end })

function Item:is_weapon() return self.kind == ItemKind.FIREARM or self.kind == ItemKind.GRENADE end
function Item:weapon() return self:is_weapon() and require("data.weapons").get(self.id) or nil end
-- Armor: +0x25 / +0x26 are the two armor values (doc 08) [C values; ballistic/impact naming H]
function Item:armor_values()
    if self.kind ~= ItemKind.ARMOR then return nil end
    return self.b25, self.b26
end
-- Totems: +0x22, +0x24/+0x25 word and +0x26 are the 3 spell-category dice modifiers (0x1054A) [C reader; H exact words]
function Item:totem_modifiers()
    if self.kind ~= ItemKind.TOTEM then return nil end
    local w2 = (self.b24 << 8) | self.b25
    return self.price, w2, self.b26
end
-- +0x27 action motion distance row (only Bear Totem = 2; read by 0x13D0C, doc 08) [C]
function Item:motion_row() return self.b27 end
-- Shop buy price: 0x57A6E applies shop discounts and Negotiation; that logic lives in logic/shop.lua (not yet written).

